-/* Motion & finishing touches */
+/* Northstar design system — application layer.
+   Consumes ONLY tokens from src/tokens.css. Do not hardcode
+   px font sizes, hex colors, or raw accent washes here.
+
+   Patterns:
+   • typography ......... var(--text-*)  (+ var(--font-mono))
+   • surfaces/borders ... var(--panel-*), var(--line-*), var(--text-*)
+   • accent washes ...... color-mix(in srgb, var(--accent) N%, transparent)
+   • spacing / radius ... var(--space-*), var(--radius-*)
+*/
+
+/* ── Shell & topbar ─────────────────────────────────────────── */
+.app-shell{min-height:100vh;background:var(--bg);background-image:radial-gradient(circle at 71% 1%,color-mix(in srgb,var(--accent) 9%,transparent),transparent 28rem)}
+
+.topbar{height:68px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:blur(18px);display:flex;align-items:center;padding:0 var(--space-7);gap:var(--space-7);position:sticky;top:0;z-index:10}
+.brand,.top-links,.top-search,.hero-actions,.showcase-foot,.status-line,.code-head,.section-heading,.release-icon,.input-with-action,.toggle-field{display:flex;align-items:center}
+
+.brand{gap:10px;white-space:nowrap}
+.brand-mark{width:26px;height:26px;border:1px solid var(--accent);border-radius:var(--radius-md);display:grid;place-items:center;transform:rotate(45deg)}
+.brand-mark span{width:9px;height:9px;background:var(--accent);border-radius:3px}
+.brand-mark.large{width:42px;height:42px;border-radius:var(--radius-xl)}
+.brand-mark.large span{width:14px;height:14px}
+.brand b{font-weight:800;letter-spacing:-.04em;font-size:var(--text-base)}
+
+.version,.api-pill,.nav-count{font:var(--text-3xs) var(--font-mono);color:var(--muted);border:1px solid var(--line);padding:var(--space-1) 7px;border-radius:var(--radius-sm)}
+
+.top-search{max-width:380px;flex:1;margin-left:auto;margin-right:auto;gap:10px;color:var(--subtle);background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:var(--space-2) 11px}
+.top-search:focus-within{border-color:var(--line-focus)}
+.top-search input{background:none;border:0;outline:0;color:var(--text);min-width:0;flex:1;font-size:var(--text-sm)}
+.top-search kbd{font:var(--text-3xs) var(--font-mono);color:var(--subtle);border:1px solid var(--line);border-radius:4px;padding:var(--space-1) var(--space-1)}
+
+.top-links{gap:var(--space-5);font-size:var(--text-sm);color:var(--muted)}
+.top-links a:hover,.text-button:hover{color:var(--text)}
+
+.icon-button,.avatar{border:0;background:none;color:var(--muted);display:grid;place-items:center;padding:7px;border-radius:var(--radius-md)}
+.icon-button:hover{background:var(--panel-3);color:var(--text)}
+.avatar{width:28px;height:28px;background:color-mix(in srgb,var(--accent) 14%,var(--panel-2));color:color-mix(in srgb,var(--accent) 85%,white);font-size:var(--text-3xs);font-weight:700}
+.mobile-menu{display:none}
+
+.body-layout{display:grid;grid-template-columns:240px minmax(0,1fr)}
+
+/* ── Sidebar ────────────────────────────────────────────────── */
+.sidebar{border-right:1px solid var(--line);min-height:calc(100vh - 68px);padding:var(--space-7) var(--space-4) var(--space-6);display:flex;flex-direction:column;position:sticky;top:68px;height:calc(100vh - 68px)}
+.sidebar-intro{padding:0 var(--space-3) var(--space-7);border-bottom:1px solid var(--line);margin-bottom:var(--space-6)}
+.sidebar-intro p{font-size:var(--text-3xs);line-height:1.6;color:var(--subtle);margin:var(--space-2) 0 0;max-width:150px}
+
+.eyebrow,.section-index,.nav-label{font:var(--text-3xs) var(--font-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--subtle)}
+.accent{color:var(--accent)}
+
+.nav-group{margin-bottom:var(--space-6)}
+.nav-label{display:block;padding:0 var(--space-3);margin-bottom:9px}
