+.hero-section{animation:rise-in .7s cubic-bezier(.2,.8,.2,1) both}
+.hero-copy h1{background:linear-gradient(110deg,var(--text-bright) 15%,var(--accent) 55%,var(--text-bright) 85%);background-size:220% auto;background-clip:text;-webkit-background-clip:text;color:transparent;animation:shimmer 9s linear infinite}
+.hero-copy p{animation:rise-in .7s .1s cubic-bezier(.2,.8,.2,1) both}
+.hero-actions{animation:rise-in .7s .18s cubic-bezier(.2,.8,.2,1) both}
+.hero-orbit{animation:rise-in .9s .18s cubic-bezier(.2,.8,.2,1) both}
+.orbit-one{animation:orbit-drift 24s linear infinite}
+.orbit-two{animation:orbit-drift-reverse 30s linear infinite}
+.orbit-core{animation:soft-glow 4s ease-in-out infinite}
+.orbit-label{animation:rise-in .7s .7s both}
+.section-block{animation:rise-in .65s .1s cubic-bezier(.2,.8,.2,1) both}
+.section-block:nth-child(2){animation-delay:.16s}
+.section-block:nth-child(3){animation-delay:.22s}
+.section-block:nth-child(4){animation-delay:.28s}
+.button-row{transition:background .25s ease,transform .25s ease}
+.button-row:hover{background:color-mix(in srgb,var(--accent) 4%,transparent);transform:translateX(3px)}
+.button{position:relative;overflow:hidden}
+.button:not(:disabled)::after,.copy-button::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 25%,rgba(255,255,255,.13) 50%,transparent 75%);transform:translateX(-120%);transition:transform .55s ease}
+.button:hover::after,.copy-button:hover::after{transform:translateX(120%)}
+.button:focus-visible,.tab:focus-visible,.nav-item:focus-visible,.density:focus-visible,.segmented button:focus-visible,.text-button:focus-visible{outline:var(--focus-ring);outline-offset:var(--focus-offset)}
+.button.primary{box-shadow:0 5px 18px color-mix(in srgb,var(--accent) 18%,transparent)}
+.button.primary:active{transform:translateY(1px) scale(.98)}
+.button.secondary:hover,.button.ghost:hover,.density:hover{border-color:var(--line-hover)}
+.swatch{transition:transform .3s ease,box-shadow .3s ease}
+.color-card{transition:transform .25s ease,border-color .25s ease,background .25s ease}
+.color-card:hover{transform:translateY(-4px);border-color:var(--line-hover);background:var(--panel-hover)}
+.color-card:hover .swatch{transform:scale(1.08);box-shadow:0 0 18px color-mix(in srgb,var(--accent) 30%,transparent),inset 0 0 0 1px rgba(255,255,255,.2)}
+.nav-item{position:relative}
+.nav-item::after{content:"";position:absolute;right:10px;width:0;height:1px;background:var(--accent);transition:width .25s ease}
+.nav-item:hover::after{width:12px}
+.status-dot{animation:pulse-dot 2.5s ease-in-out infinite}
+.field input,.input-with-action{transition:border-color .25s ease,box-shadow .25s ease,background .25s ease}
+.field input:hover,.input-with-action:hover{background:var(--panel-hover);border-color:var(--line-hover)}
+.field input:focus,.input-with-action:focus-within{box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 8%,transparent),0 0 20px color-mix(in srgb,var(--accent) 6%,transparent)}
+.toggle{transition:background .25s ease,transform .2s ease}
+.toggle:active{transform:scale(.94)}
+.release{transition:transform .3s ease,box-shadow .3s ease}
+.release:hover{transform:translateY(-4px);box-shadow:0 14px 38px rgba(0,0,0,.2),0 0 25px color-mix(in srgb,var(--accent) 6%,transparent)}
+.release-icon{transition:transform .4s cubic-bezier(.2,.8,.2,1)}
+.release:hover .release-icon{transform:rotate(-8deg) scale(1.08)}
+.code-card{transition:border-color .3s ease,box-shadow .3s ease}
+.code-card:hover{border-color:var(--line-hover);box-shadow:0 15px 40px rgba(0,0,0,.14)}
+.copy-button{position:relative;overflow:hidden}
+.top-search{transition:border-color .25s ease,box-shadow .25s ease}
+.top-search:hover{border-color:var(--line-hover)}
+.top-search:focus-within{box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 6%,transparent)}
+
+@media(prefers-reduced-motion:reduce){
+  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}
+  .hero-copy h1{background:none;color:var(--text)}
+}
+
+/* ── Sidebar refinement: editorial, flat, easy to scan ──────── */
+.sidebar{padding:var(--space-5) 0 var(--space-4);background:linear-gradient(180deg,var(--bg-deep) 0%,var(--bg) 76%)}
+.sidebar-heading{display:flex;align-items:center;justify-content:space-between;padding:0 var(--space-5) var(--space-5);border-bottom:1px solid var(--line)}
+.sidebar-library{display:flex;align-items:center;gap:var(--space-2);color:var(--text);font:500 var(--text-xs) var(--font-mono);letter-spacing:.05em;text-transform:uppercase}
+.sidebar-library svg{color:var(--accent)}
+.sidebar-collapse{border:0;background:none;color:var(--subtle);font:var(--text-xs) var(--font-mono);padding:4px 0}
+.sidebar-collapse:hover{color:var(--text)}
+.sidebar-intro{padding:var(--space-5) var(--space-5) var(--space-5);margin:0;border-bottom:1px solid var(--line)}
+.sidebar-intro p{max-width:180px;margin-top:var(--space-2)}
+.sidebar nav{padding-top:var(--space-5)}
+.nav-group{margin-bottom:var(--space-5)}
+.nav-label{padding:0 var(--space-5);margin-bottom:var(--space-2);color:var(--subtle);font-size:var(--text-3xs)}
+.nav-item{position:relative;width:100%;border-radius:0;padding:9px var(--space-5);gap:11px;letter-spacing:-.01em}
+.nav-item:hover{background:var(--panel-hover)}
+.nav-item.active{background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 15%,transparent),color-mix(in srgb,var(--accent) 4%,transparent));box-shadow:inset 2px 0 var(--accent);color:var(--text-bright)}
+.nav-item.active::before{content:"";position:absolute;right:var(--space-5);width:5px;height:5px;border-radius:50%;background:var(--accent);box-shadow:0 0 10px color-mix(in srgb,var(--accent) 80%,transparent)}
+.nav-item::after{display:none}
+.nav-glyph{width:13px;color:var(--subtle);font:var(--text-md) var(--font-mono);line-height:1;text-align:center}
+.nav-item.active .nav-glyph{color:var(--accent)}
+.nav-count{border:0;padding:0;margin-left:auto;color:color-mix(in srgb,var(--accent) 60%,var(--subtle));background:none;font-size:var(--text-3xs)}
+.sidebar-bottom{padding:var(--space-4) var(--space-5) 0}
+.sidebar-bottom .status-line{font-size:var(--text-3xs)}
+
+@media(max-width:760px){
+  .sidebar{padding-top:var(--space-4)}
+  .sidebar-heading{padding-left:var(--space-5);padding-right:var(--space-5)}
+  .sidebar-intro{padding-top:var(--space-4)}
+  .sidebar nav{padding-top:var(--space-5)}
+  .nav-item{padding-top:10px;padding-bottom:10px}
+}
